{
  "model": "={{ $env.VLM_MODEL_NAME || 'gemini-3.8-flash' }}",
  "messages": [
    {
      "role": "system",
      "content": "Ты — технический эксперт по оснащению санузлов оборудованием Tork (Essity). Проанализируй фотографию помещения.\n1. Определи, является ли фото валидным изображением санузла/умывальной зоны, где видна стена для монтажа диспенсера (is_valid_washroom: boolean). Если фото снято слишком близко, темно или это не санузел — укажи причину отказа на русском языке в поле rejection_reason.\n2. Определи цветовую гамму и стиль интерьера и выбери рекомендуемый цвет оборудования (recommended_color: white, black или stainless_steel). Для темных, лофтовых и современных интерьеров выбирай black или stainless_steel, для классических светлых и медицинских — white.\n3. Найди на фото раковину или зеркало как ориентир масштаба (стандартная ширина раковины = 55 см). Опиши на английском языке точное место на стене для вставки диспенсера для полотенец и дозатора мыла в поле placement_instruction_en (например: Mount the dispenser on the tiled wall to the right of the mirror, 25 cm above the sink counter).\nВерни ответ СТРОГО в формате JSON."
    },
    {
      "role": "user",
      "content": [
        {
          "type": "text",
          "text": "Пожалуйста, проанализируй это фото санузла."
        },
        {
          "type": "image_url",
          "image_url": {
            "url": "={{ $json.photo_base64_url }}"
          }
        }
      ]
    }
  ],
  "response_format": {
    "type": "json_object"
  }
}

{
  "contents": [
    {
      "parts": [
        {
          "text": "={{ 'Composite the exact Tork dispenser from the second image onto the washroom wall in the first image. Location: ' + ($json.placement_instruction_en || 'Mount the dispenser on the wall to the side of the sink') + '. Preserve the exact product shape, Tork logo, and material from the second reference image. Real product dimensions: width ' + ($json.dimensions_cm?.w || 33.7) + ' cm, height ' + ($json.dimensions_cm?.h || 37.2) + ' cm (scale it realistically relative to the sink, which is ~55 cm wide). Cast natural soft contact shadows onto the wall tiles matching the existing room lighting. Do not alter the rest of the bathroom.' }}"
        },
        {
          "inline_data": {
            "mime_type": "image/jpeg",
            "data": "={{ $json.photo_base64 || '' }}"
          }
        },
        {
          "inline_data": {
            "mime_type": "image/png",
            "data": "={{ $json.dispenser_clean_base64 || '' }}"
          }
        }
      ]
    }
  ],
  "generationConfig": {
    "responseModalities": [
      "IMAGE"
    ]
  }
}

parameters.jsCode:
// Расчет спецификации и сборка HTML коммерческого предложения
const items = $input.all().map(item => item.json);
const session = items[0]?.session || {};
const distributor = items[0]?.distributor || {};
const visualData = items[0]?.visual || {};

// Извлечение сгенерированного изображения из структуры Google Gemini API
// candidates[0].content.parts[0].inlineData.data (с поддержкой inline_data и fallback)
let base64Image = '';
const candidatePart = items[0]?.candidates?.[0]?.content?.parts?.[0];
if (candidatePart?.inlineData?.data) {
  base64Image = candidatePart.inlineData.data;
} else if (candidatePart?.inline_data?.data) {
  base64Image = candidatePart.inline_data.data;
} else if (items[0]?.data?.[0]?.b64_json) {
  base64Image = items[0].data[0].b64_json;
} else if (items[0]?.rendered_image_base64) {
  base64Image = items[0].rendered_image_base64;
}

const mimeType = candidatePart?.inlineData?.mimeType || candidatePart?.inline_data?.mime_type || 'image/png';
const renderedImageDataUri = base64Image
  ? `data:${mimeType};base64,${base64Image}`
  : 'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="240" height="160"><rect width="240" height="160" fill="%23edf2f7"/><text x="50%" y="50%" dominant-baseline="middle" text-anchor="middle" fill="%23718096" font-size="12">Визуализация Tork Elevation</text></svg>';

let rowsHtml = '';
let totalSum = 0;
let rowIdx = 1;

for (const prod of items) {
  if (!prod.sku) continue;
  const qty = prod.category === 'dispenser'
    ? 1
    : Math.ceil(((session.daily_traffic || 100) * 30 * (prod.refill_norms?.daily_use_per_person || 2)) / (prod.refill_norms?.portions_per_unit || 1000));
  const lineSum = Number(prod.price || 0) * qty;
  totalSum += lineSum;

  rowsHtml += `
    <tr>
      <td class="text-center">${rowIdx++}</td>
      <td><strong>${prod.sku}</strong></td>
      <td>${prod.name || 'Продукция Tork'}</td>
      <td class="text-center"><span class="badge">${prod.system_code || 'H1'}</span></td>
      <td class="text-center">${qty}</td>
      <td class="text-right">${Number(prod.price || 0).toLocaleString('ru-RU')} ₸</td>
      <td class="text-right"><strong>${lineSum.toLocaleString('ru-RU')} ₸</strong></td>
    </tr>
  `;
}

return [{
  json: {
    total_amount_formatted: totalSum.toLocaleString('ru-RU'),
    table_rows_html: rowsHtml,
    kp_number: 'TKZ-' + Date.now().toString().slice(-6),
    kp_date: new Date().toLocaleDateString('ru-RU'),
    distributor_name: distributor.name || 'ТОО "Tork Kazakhstan Distribution Astana"',
    distributor_bin: distributor.bin || '210540032111',
    distributor_city: distributor.city || 'Астана',
    distributor_address: distributor.address || 'г. Астана, ул. Достык, 18',
    distributor_phone: distributor.contact_phone || '+7 (7172) 79-55-01',
    distributor_email: distributor.contact_email || 'astana@tork-distrib.kz',
    client_name: session.client_name || 'Уважаемый клиент',
    business_segment: session.business_segment || 'Коммерческий объект',
    daily_traffic: session.daily_traffic || 100,
    recommended_color_ru: visualData.recommended_color === 'black' ? 'Черный' : (visualData.recommended_color === 'stainless_steel' ? 'Нержавеющая сталь' : 'Белый'),
    placement_instruction_ru: 'Монтаж на капитальную стену над/рядом с зоной раковины с соблюдением стандартов доступности Essity Tork.',
    rendered_image_data_uri: renderedImageDataUri
  }
}];
